     6	/** Toda mensagem enviada gera uma cópia para o arquivo, logo depois da original. */
     7	public class ArchiveCopyRule implements DispatchRule {
     8	    public static final String ARCHIVE_ADDRESS = "arquivo@pousadamarealta.com.br";
