    13	        if (result.stream().anyMatch(Message::isSent)) {
    14	            result.add(Message.draft(message.channel(), ARCHIVE_ADDRESS,
    15	                    "[Cópia] " + message.subject(), message.body()));
    16	        }
    17	        return result;
    18	    }
    19	}
