=== messaging/DispatchRules.java
     1	package br.com.marealta.messaging;
     2	
     3	import java.util.List;
     4	
     5	/**
     6	 * Único lugar que lista as regras de envio, em ordem, e em que modo cada uma vale.
     7	 * Para uma regra nova (horário, limite por hóspede...), crie um DispatchRule e acrescente uma linha aqui.
     8	 */
     9	public final class DispatchRules {
    10	    private record Entry(RuleScope scope, DispatchRule rule) {}
    11	
    12	    private DispatchRules() {}
    13	
    14	    public static List<DispatchRule> forMode(boolean testMode) {
    15	        List<Entry> entries = List.of(
    16	                new Entry(RuleScope.ALWAYS, new InvalidAddressRule()),
    17	                new Entry(RuleScope.TEST_ONLY, new TestRedirectRule()),
    18	                new Entry(RuleScope.NON_TEST_ONLY, new ArchiveCopyRule()));
    19	        return entries.stream()
    20	                .filter(entry -> entry.scope().appliesTo(testMode))
    21	                .map(Entry::rule)
    22	                .toList();
    23	    }
    24	}
