     1	package br.com.marealta.messaging;
     2	
     3	public final class EmailAddress {
     4	    private EmailAddress() {}
     5	
     6	    /** Um único @, algo antes dele e, depois, um nome com pelo menos um ponto no meio. */
     7	    public static boolean isValid(String address) {
     8	        if (address == null || address.chars().anyMatch(Character::isWhitespace)) return false;
     9	        int at = address.indexOf('@');
    10	        if (at <= 0 || at != address.lastIndexOf('@')) return false;
    11	        String domain = address.substring(at + 1);
    12	        if (!domain.contains(".")) return false;
    13	        for (String label : domain.split("\\.", -1)) {
    14	            if (label.isEmpty()) return false;
    15	        }
    16	        return true;
    17	    }
    18	}
