=== messaging/Notifier.java
     1	package br.com.marealta.messaging;
     2	
     3	import java.util.List;
     4	
     5	/** Passa cada mensagem pela cadeia de regras e guarda o resultado na lista de mensagens. */
     6	public class Notifier {
     7	    private final DispatchRule.Next chain;
     8	    private final MessageLog log;
     9	
    10	    public Notifier(List<DispatchRule> rules, MessageLog log) {
    11	        this.log = log;
    12	        DispatchRule.Next next = message -> List.of(message);
    13	        for (int i = rules.size() - 1; i >= 0; i--) {
    14	            DispatchRule rule = rules.get(i);
    15	            DispatchRule.Next following = next;
    16	            next = message -> rule.apply(message, following);
    17	        }
    18	        this.chain = next;
    19	    }
    20	
    21	    public void send(Channel channel, String to, String subject, String body) {
    22	        log.addAll(chain.send(Message.draft(channel, to, subject, body)));
    23	    }
    24	}
