=== web/App.java
     1	package br.com.marealta.web;
     2	
     3	import br.com.marealta.domain.DomainException;
     4	import br.com.marealta.messaging.DispatchRules;
     5	import br.com.marealta.messaging.MessageLog;
     6	import br.com.marealta.messaging.Notifier;
     7	import br.com.marealta.service.ReportService;
     8	import br.com.marealta.service.ReservationRepository;
     9	import br.com.marealta.service.ReservationService;
    10	import br.com.marealta.service.RoomCatalog;
    11	import com.fasterxml.jackson.databind.ObjectMapper;
    12	import com.fasterxml.jackson.databind.SerializationFeature;
    13	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
    14	import io.javalin.Javalin;
    15	import io.javalin.json.JavalinJackson;
    16	
    17	import java.util.Map;
    18	
    19	public final class App {
    20	    private App() {}
    21	
    22	    public static Javalin create(boolean testMode) {
    23	        RoomCatalog rooms = new RoomCatalog();
    24	        ReservationRepository repository = new ReservationRepository();
    25	        MessageLog log = new MessageLog();
    26	        Notifier notifier = new Notifier(DispatchRules.forMode(testMode), log);
    27	        ReservationService reservations = new ReservationService(rooms, repository, notifier);
    28	        ReportService reports = new ReportService(rooms, repository);
    29	
    30	        ObjectMapper mapper = new ObjectMapper()
    31	                .registerModule(new JavaTimeModule())
    32	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    33	
    34	        Javalin app = Javalin.create(config -> config.jsonMapper(new JavalinJackson(mapper, false)));
    35	
    36	        app.exception(DomainException.class, (e, ctx) ->
    37	                ctx.status(e.status()).json(Map.of("error", e.code(), "message", e.getMessage())));
    38	
    39	        app.get("/rooms", ctx -> ctx.json(rooms.all().stream().map(RoomView::of).toList()));
    40	
    41	        app.post("/reservations", ctx -> {
    42	            var created = reservations.create(RequestParser.reservation(ctx.body()));
    43	            ctx.status(201).json(ReservationView.of(created));
    44	        });
    45	        app.get("/reservations/{id}", ctx ->
    46	                ctx.json(ReservationView.of(reservations.get(ctx.pathParam("id")))));
    47	        app.post("/reservations/{id}/confirmation", ctx ->
    48	                ctx.json(ReservationView.of(reservations.confirm(ctx.pathParam("id")))));
    49	        app.post("/reservations/{id}/cancellation", ctx ->
    50	                ctx.json(ReservationView.of(reservations.cancel(ctx.pathParam("id")))));
    51	        app.post("/reservations/{id}/check-in", ctx ->
    52	                ctx.json(ReservationView.of(reservations.checkIn(ctx.pathParam("id")))));
    53	        app.post("/reservations/{id}/check-out", ctx ->
    54	                ctx.json(reservations.checkOut(ctx.pathParam("id"))));
    55	        app.get("/reservations/{id}/document", ctx ->
    56	                ctx.json(reservations.document(ctx.pathParam("id"))));
    57	
    58	        app.get("/messages", ctx -> ctx.json(log.all()));
    59	
    60	        app.get("/reports/occupancy", ctx -> ctx
    61	                .contentType("text/csv; charset=utf-8")
    62	                .result(reports.occupancy(RequestParser.date(ctx.queryParam("date"), "date"))));
    63	        app.get("/reports/revenue", ctx -> ctx
    64	                .contentType("text/csv; charset=utf-8")
    65	                .result(reports.revenue(RequestParser.month(ctx.queryParam("month")))));
    66	
    67	        return app;
    68	    }
    69	}
=== web/RequestParser.java
     1	package br.com.marealta.web;
     2	
     3	import br.com.marealta.domain.DomainException;
     4	import br.com.marealta.domain.RatePlan;
     5	import br.com.marealta.service.NewReservation;
     6	import com.fasterxml.jackson.databind.JsonNode;
     7	import com.fasterxml.jackson.databind.ObjectMapper;
     8	
     9	import java.time.LocalDate;
    10	import java.time.YearMonth;
    11	import java.time.format.DateTimeParseException;
    12	
    13	/** Valida o corpo e os parâmetros vindos do site; qualquer problema vira INVALID_REQUEST. */
    14	public final class RequestParser {
    15	    private static final ObjectMapper MAPPER = new ObjectMapper();
    16	
    17	    private RequestParser() {}
    18	
    19	    public static NewReservation reservation(String body) {
    20	        JsonNode json;
    21	        try {
    22	            json = MAPPER.readTree(body);
    23	        } catch (Exception e) {
    24	            throw DomainException.invalidRequest("O corpo não é um JSON válido");
    25	        }
    26	        if (json == null || !json.isObject()) {
    27	            throw DomainException.invalidRequest("O corpo deve ser um objeto JSON");
    28	        }
    29	        return new NewReservation(
    30	                integer(json, "roomNumber"),
    31	                text(json, "guestName"),
    32	                text(json, "guestEmail"),
    33	                text(json, "guestCpf"),
    34	                date(text(json, "checkIn"), "checkIn"),
    35	                date(text(json, "checkOut"), "checkOut"),
    36	                integer(json, "guests"),
    37	                ratePlan(text(json, "ratePlan")));
    38	    }
    39	
    40	    public static LocalDate date(String value, String field) {
    41	        try {
    42	            return LocalDate.parse(value);
    43	        } catch (DateTimeParseException | NullPointerException e) {
    44	            throw DomainException.invalidRequest("Data inválida em " + field + " (use AAAA-MM-DD)");
    45	        }
    46	    }
    47	
    48	    public static YearMonth month(String value) {
    49	        try {
    50	            if (value == null || !value.matches("\\d{4}-\\d{2}")) throw new DateTimeParseException("", "", 0);
    51	            return YearMonth.parse(value);
    52	        } catch (DateTimeParseException e) {
    53	            throw DomainException.invalidRequest("Mês inválido (use AAAA-MM)");
    54	        }
    55	    }
    56	
    57	    private static String text(JsonNode json, String field) {
    58	        JsonNode node = json.get(field);
    59	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    60	            throw DomainException.invalidRequest("Campo obrigatório ausente ou inválido: " + field);
    61	        }
    62	        return node.asText();
    63	    }
    64	
    65	    private static int integer(JsonNode json, String field) {
    66	        JsonNode node = json.get(field);
    67	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    68	            throw DomainException.invalidRequest("Campo obrigatório ausente ou inválido: " + field);
    69	        }
    70	        return node.intValue();
    71	    }
    72	
    73	    private static RatePlan ratePlan(String value) {
    74	        try {
    75	            return RatePlan.valueOf(value);
    76	        } catch (IllegalArgumentException e) {
    77	            throw DomainException.invalidRequest("Plano de tarifa inválido: " + value);
    78	        }
    79	    }
    80	}
