     7	import java.time.LocalDate;
     8	import java.time.YearMonth;
     9	import java.util.Comparator;
    10	import java.util.List;
    11	
    12	public class ReportService {
    13	    private final RoomCatalog rooms;
    14	    private final ReservationRepository repository;
    15	
    16	    public ReportService(RoomCatalog rooms, ReservationRepository repository) {
    17	        this.rooms = rooms;
    18	        this.repository = repository;
    19	    }
    20	
    21	    public String occupancy(LocalDate night) {
    22	        List<Reservation> occupying;
    23	        synchronized (repository) {
    24	            occupying = repository.all().stream()
    25	                    .filter(r -> r.occupiesNight(night))
    26	                    .sorted(Comparator.comparingInt((Reservation r) -> r.room().number()))
    27	                    .toList();
    28	        }
    29	        StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    30	        for (Reservation r : occupying) {
    31	            csv.append(r.room().number()).append(',').append(r.room().type()).append(',')
    32	                    .append(r.id()).append(',').append(r.checkIn()).append(',').append(r.checkOut()).append('\n');
    33	        }
    34	        return csv.append("total,").append(occupying.size()).append('/').append(rooms.all().size())
    35	                .append('\n').toString();
    36	    }
    37	
    38	    public String revenue(YearMonth month) {
    39	        List<Reservation> kept;
    40	        synchronized (repository) {
    41	            kept = repository.all().stream()
    42	                    .filter(r -> YearMonth.from(r.checkIn()).equals(month))
    43	                    .filter(r -> r.amountKept().signum() > 0)
    44	                    .sorted(Comparator.comparing(Reservation::checkIn).thenComparingInt(Reservation::id))
    45	                    .toList();
    46	        }
    47	        StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    48	        BigDecimal total = Money.ZERO;
    49	        for (Reservation r : kept) {
    50	            csv.append(r.id()).append(',').append(r.room().number()).append(',')
    51	                    .append(r.checkIn()).append(',').append(r.checkOut()).append(',')
    52	                    .append(r.status()).append(',').append(r.amountKept().toPlainString()).append('\n');
    53	            total = total.add(r.amountKept());
    54	        }
    55	        return csv.append("total,").append(total.toPlainString()).append('\n').toString();
    56	    }
    57	}
