     9	/** Reservas em memória. Quem precisa de consistência entre várias operações sincroniza no próprio repositório. */
    10	public class ReservationRepository {
    11	    private final List<Reservation> reservations = new ArrayList<>();
    12	
    13	    public synchronized int nextId() { return reservations.size() + 1; }
    14	
    15	    public synchronized void add(Reservation reservation) { reservations.add(reservation); }
    16	
    17	    public synchronized Optional<Reservation> find(int id) {
    18	        return id >= 1 && id <= reservations.size() ? Optional.of(reservations.get(id - 1)) : Optional.empty();
    19	    }
    20	
    21	    public synchronized List<Reservation> all() { return List.copyOf(reservations); }
    22	}
