     9	public class ReservationService {
    10	    static final String CONFIRMATION_SUBJECT = "Reserva confirmada - Pousada Maré Alta";
    11	
    12	    private final RoomCatalog rooms;
    13	    private final ReservationRepository repository;
    14	    private final Notifier notifier;
    15	
    16	    public ReservationService(RoomCatalog rooms, ReservationRepository repository, Notifier notifier) {
    17	        this.rooms = rooms;
    18	        this.repository = repository;
    19	        this.notifier = notifier;
    20	    }
    21	
    22	    public Reservation create(NewReservation request) {
    23	        if (!request.checkOut().isAfter(request.checkIn())) {
    24	            throw DomainException.invalidRequest("A saída deve ser depois da entrada");
    25	        }
    26	        if (request.guests() < 1) {
    27	            throw DomainException.invalidRequest("É preciso pelo menos um hóspede");
    28	        }
    29	        Room room = rooms.find(request.roomNumber())
    30	                .orElseThrow(() -> DomainException.roomNotFound(String.valueOf(request.roomNumber())));
    31	        if (request.guests() > room.capacity()) {
    32	            throw DomainException.capacityExceeded(room.capacity());
    33	        }
    34	        synchronized (repository) {
    35	            boolean taken = repository.all().stream()
    36	                    .anyMatch(r -> r.room().equals(room) && r.overlaps(request.checkIn(), request.checkOut()));
    37	            if (taken) throw DomainException.roomUnavailable();
    38	            Reservation reservation = new Reservation(repository.nextId(), room, request.guestName(),
    39	                    request.guestEmail(), request.guestCpf(), request.checkIn(), request.checkOut(),
    40	                    request.guests(), request.ratePlan());
    41	            repository.add(reservation);
    42	            return reservation;
    43	        }
    44	    }
    45	
    46	    public Reservation get(String id) {
    47	        return repository.find(parseId(id)).orElseThrow(() -> DomainException.reservationNotFound(id));
    48	    }
    49	
    50	    public Reservation confirm(String id) {
    51	        synchronized (repository) {
    52	            Reservation reservation = get(id);
    53	            reservation.confirm();
    54	            notifier.send(Channel.EMAIL, reservation.guestEmail(), CONFIRMATION_SUBJECT,
    55	                    ReceiptFormatter.confirmationEmail(reservation.guestName(), Receipt.of(reservation)));
    56	            return reservation;
    57	        }
    58	    }
    59	
    60	    public Reservation cancel(String id) {
    61	        synchronized (repository) {
    62	            Reservation reservation = get(id);
    63	            reservation.cancel();
    64	            return reservation;
    65	        }
    66	    }
    67	
    68	    public Reservation checkIn(String id) {
    69	        synchronized (repository) {
    70	            Reservation reservation = get(id);
    71	            reservation.performCheckIn();
    72	            return reservation;
    73	        }
    74	    }
    75	
    76	    public Receipt checkOut(String id) {
    77	        synchronized (repository) {
    78	            Reservation reservation = get(id);
    79	            reservation.performCheckOut();
    80	            return Receipt.of(reservation);
    81	        }
    82	    }
