    37	    public void confirm() {
    38	        require(PENDING, "Só é possível confirmar uma reserva pendente");
    39	        status = CONFIRMED;
    40	        amountPaid = quote.total();
    41	    }
    42	
    43	    public void performCheckIn() {
    44	        require(CONFIRMED, "Só é possível fazer check-in de uma reserva confirmada");
    45	        status = CHECKED_IN;
    46	    }
