    48	    public void performCheckOut() {
    49	        require(CHECKED_IN, "Só é possível fazer check-out de uma reserva com check-in");
    50	        status = CHECKED_OUT;
    51	    }
    52	
    53	    public void cancel() {
    54	        if (status != PENDING && status != CONFIRMED) {
    55	            throw DomainException.notAllowed("Só é possível cancelar antes do check-in");
    56	        }
    57	        refund = ratePlan.refund(amountPaid);
    58	        status = CANCELLED;
    59	    }
