     9	
    10	class MessagingTest {
    11	    private List<Message> send(boolean testMode, String to) {
    12	        MessageLog log = new MessageLog();
    13	        new Notifier(DispatchRules.forMode(testMode), log).send(Channel.EMAIL, to, "Assunto", "Texto");
    14	        return log.all();
    15	    }
    16	
    17	    @Test
    18	    void normalModeSendsAndArchives() {
    19	        List<Message> m = send(false, "ana@gmail.com");
    20	        assertEquals(2, m.size());
    21	        assertEquals("ana@gmail.com", m.get(0).to());
    22	        assertEquals(MessageStatus.SENT, m.get(0).status());
    23	        assertEquals("arquivo@pousadamarealta.com.br", m.get(1).to());
    24	        assertEquals("[Cópia] Assunto", m.get(1).subject());
    25	        assertEquals(2, m.get(1).id());
    26	    }
    27	
    28	    @Test
    29	    void invalidAddressIsBlockedWithoutCopy() {
    30	        for (String bad : List.of("ana@gmail", "ana.gmail.com", "a@@b.com", "@b.com", "a@b.", "a@.com")) {
    31	            List<Message> m = send(false, bad);
    32	            assertEquals(1, m.size(), bad);
    33	            assertEquals(MessageStatus.BLOCKED, m.get(0).status());
    34	            assertEquals(bad, m.get(0).to());
    35	        }
    36	    }
    37	
    38	    @Test
    39	    void testModeRedirects() {
    40	        List<Message> m = send(true, "ana@gmail.com");
    41	        assertEquals(1, m.size());
    42	        assertEquals("testes@pousadamarealta.com.br", m.get(0).to());
    43	        assertEquals("[TESTE] Assunto", m.get(0).subject());
    44	        assertEquals("Destinatário original: ana@gmail.com\nTexto", m.get(0).body());
    45	    }
    46	
    47	    @Test
    48	    void testModeStillBlocksInvalidWithOriginalAddress() {
    49	        List<Message> m = send(true, "ana@gmail");
    50	        assertEquals(1, m.size());
    51	        assertEquals(MessageStatus.BLOCKED, m.get(0).status());
    52	        assertEquals("ana@gmail", m.get(0).to());
    53	        assertEquals("Assunto", m.get(0).subject());
    54	    }
    55	}
